<script setup lang="ts">
import { ExternalLink, Maximize2, Minimize2, Minus, Monitor, RotateCw, Smartphone, Tablet, X } from 'lucide-vue-next'
import { projects } from '~/data/projects'
import type { LabWindow } from '~/stores/desktop'
const desktop = useDesktopStore()
const baseURL = useRuntimeConfig().app.baseURL
const demoURL = (id: string) => baseURL + project(id).url.replace(/^\//, '')
const reloads = reactive<Record<string, number>>({})
const loaded = reactive<Record<string, boolean>>({})
let drag: { id: string; x: number; y: number; originX: number; originY: number } | null = null
function start(e: PointerEvent, w: LabWindow) { if ((e.target as HTMLElement).closest('button') || w.maximized || window.innerWidth < 768) return; drag = { id: w.id, x: e.clientX, y: e.clientY, originX: w.x, originY: w.y }; (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId); desktop.focus(w.id) }
function move(e: PointerEvent) { if (!drag) return; const w = desktop.windows.find(w => w.id === drag!.id); if (w) { w.x = Math.max(0, Math.min(window.innerWidth - 180, drag.originX + e.clientX - drag.x)); w.y = Math.max(0, Math.min(window.innerHeight - 100, drag.originY + e.clientY - drag.y)) } }
function refresh(id: string) { reloads[id] = (reloads[id] || 0) + 1; loaded[id] = false }
const project = (id: string) => projects.find(p => p.id === id)!
</script>
<template><div v-for="w in desktop.windows" v-show="!w.minimized" :key="w.id" :class="['lab-window', { maximized: w.maximized }]" :style="{ left: `${w.x}px`, top: `${w.y}px`, zIndex: w.z }" role="dialog" :aria-label="project(w.id).name" @pointerdown="desktop.focus(w.id)"><header class="window-title" @pointerdown="start($event, w)" @pointermove="move" @pointerup="drag = null" @pointercancel="drag = null"><span><span class="status-dot" /> {{ project(w.id).name }} <small>// {{ project(w.id).framework }}</small></span><div><button aria-label="Minimize window" @click="w.minimized = true"><Minus :size="16" /></button><button :aria-label="w.maximized ? 'Restore window' : 'Maximize window'" @click="w.maximized = !w.maximized"><Minimize2 v-if="w.maximized" :size="15" /><Maximize2 v-else :size="15" /></button><button aria-label="Close demo" @click="desktop.close(w.id)"><X :size="17" /></button></div></header><div class="window-toolbar"><span class="demo-tag">DEMO ENVIRONMENT</span><div class="devices"><button v-for="device in (['desktop', 'tablet', 'mobile'] as const)" :key="device" :aria-label="`${device} viewport`" :aria-pressed="w.device === device" :class="{ active: w.device === device }" @click="w.device = device"><component :is="device === 'desktop' ? Monitor : device === 'tablet' ? Tablet : Smartphone" :size="16" /></button></div><button aria-label="Reload demo" @click="refresh(w.id)"><RotateCw :size="16" /></button><a :href="demoURL(w.id)" target="_blank" rel="noopener" aria-label="Open demo in new tab"><ExternalLink :size="16" /></a></div><div class="frame-area"><p v-if="!loaded[w.id]" class="frame-loading">Mounting application… <a :href="demoURL(w.id)" target="_blank" rel="noopener">Open directly ↗</a></p><iframe :key="`${w.id}-${reloads[w.id] || 0}`" :src="demoURL(w.id)" :title="`${project(w.id).name} interactive demo`" sandbox="allow-scripts allow-same-origin allow-forms" :style="{ width: w.device === 'mobile' ? '375px' : w.device === 'tablet' ? '768px' : '100%' }" @load="loaded[w.id] = true" /></div><footer><span>{{ loaded[w.id] ? '● DOCUMENT LOADED' : '○ CONNECTING' }}</span><span>{{ w.device.toUpperCase() }} VIEWPORT / SAMPLE DATA</span></footer></div><div v-if="desktop.windows.some(w => w.minimized)" class="window-dock"><button v-for="w in desktop.windows.filter(w => w.minimized)" :key="w.id" @click="desktop.open(w.id)"><Monitor :size="14" />{{ project(w.id).name }} ↗</button></div></template>


